import React, { useEffect, useMemo, useState } from 'react';
import './admin.css';

export default function UserManagement() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // UI state
  const [searchTerm, setSearchTerm] = useState('');
  const [roleTab, setRoleTab] = useState('All'); // All, Jobseekers, Employers, Admins
  const [statusFilter, setStatusFilter] = useState('All'); // All, Active, Deactivated, Deleted
  const [selectedUser, setSelectedUser] = useState(null); // user object for modal
  const [modalOpen, setModalOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    fetchUsers();
  }, []);

  function fetchUsers() {
    setLoading(true);
    setError('');
    fetch('/api/users')
      .then(res => {
        if (!res.ok) throw new Error('Failed to fetch');
        return res.json();
      })
      .then(data => {
        // Show all accounts returned by the backend. Backend should be relied upon
        // for any server-side filtering or removal of test/mock records.
        const arr = Array.isArray(data) ? data : [];
        setUsers(arr);
        setLoading(false);
      })
      .catch(err => {
        console.error('Error fetching users:', err);
        setError('Unable to load users. Please try again later.');
        setLoading(false);
      });
  }

  // Derived list based on tabs/filters/search
  const filteredUsers = useMemo(() => {
    const term = searchTerm.trim().toLowerCase();
    return users
      .filter(u => {
        if (roleTab === 'Jobseekers') return (u.role || '').toLowerCase().includes('job');
        if (roleTab === 'Employers') return (u.role || '').toLowerCase().includes('employer');
        if (roleTab === 'Admins') return (u.role || '').toLowerCase().includes('admin');
        return true;
      })
      .filter(u => {
        if (statusFilter === 'All') return true;
        // assume backend has status field like 'active' | 'deactivated' | 'deleted'
        return (u.status || 'active').toLowerCase() === statusFilter.toLowerCase();
      })
      .filter(u => {
        if (!term) return true;
        return (
          (u.fullName || '').toLowerCase().includes(term) ||
          (u.email || '').toLowerCase().includes(term)
        );
      });
  }, [users, roleTab, statusFilter, searchTerm]);

  // Scoped styles aligned to shared dashboard look (uses `page-content` and `card` classes)
  const styles = `
    .page-content { padding: 20px; }
    .page-header { display:flex; justify-content:space-between; align-items:center; gap:12px; margin-bottom:12px }
    .page-title { margin:0; font-size:22px }
    .tabs { display:flex; gap:8px; }
    .tab { padding:8px 12px; border-radius:8px; cursor:pointer; background:#fff; border:1px solid #e5e7eb }
    .tab.active { background:var(--brand-500,#00796B); color:white; border-color:transparent }
    .controls { display:flex; gap:8px; align-items:center }
    .input { padding:8px 10px; border-radius:8px; border:1px solid #d1d5db }
    .select { padding:8px 10px; border-radius:8px; border:1px solid #d1d5db }
    .card { background:var(--card-bg,#fff); border-radius:10px; padding:16px; box-shadow:0 1px 3px rgba(15,23,42,0.06); }
    .table { width:100%; border-collapse:collapse; margin-top:12px }
    .table th, .table td { text-align:left; padding:10px; border-bottom:1px solid #eef2f7 }
    .row { cursor:pointer }
    .row:hover { background: #fbfdff }
    .badge { padding:4px 8px; border-radius:999px; font-size:12px }
    .badge.active { background:#d1fae5; color:#065f46 }
    .badge.deactivated { background:#fff4e6; color:#92400e }
    .badge.deleted { background:#fee2e2; color:#991b1b }
    .modal-backdrop { position:fixed; inset:0; background:rgba(2,6,23,0.5); display:flex; align-items:center; justify-content:center; z-index:30 }
    .modal { width:720px; max-width:95%; background:white; padding:18px; border-radius:10px; box-shadow:0 8px 24px rgba(2,6,23,0.2) }
    .form-row { display:flex; gap:8px; margin-bottom:10px }
    .form-row input, .form-row select { flex:1; padding:8px 10px; border-radius:6px; border:1px solid #e5e7eb }
    .btn { padding:8px 12px; border-radius:8px; border:none; cursor:pointer }
    .btn-primary { background:var(--brand-600,#1f6feb); color:white }
    .btn-danger { background:#ef4444; color:white }
  `;

  // Modal helpers
  function openModal(user) {
    setSelectedUser({ ...user });
    setModalOpen(true);
  }

  function closeModal() {
    setModalOpen(false);
    setSelectedUser(null);
  }

  // Save edits (name/email/password)
  async function saveUserEdits() {
    if (!selectedUser) return;
    setSaving(true);
    setError('');
    try {
      const id = selectedUser._id || selectedUser.id;
      const payload = { fullName: selectedUser.fullName, email: selectedUser.email };
      if (selectedUser.newPassword) payload.password = selectedUser.newPassword;

      const res = await fetch(`/api/users/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      if (!res.ok) throw new Error('Failed to save');
      const updated = await res.json();
      // update local list
      setUsers(prev => prev.map(u => (u._id === updated._id || u.id === updated.id ? updated : u)));
      setSaving(false);
      closeModal();
    } catch (err) {
      console.error(err);
      setError('Failed to save changes.');
      setSaving(false);
    }
  }

  // Toggle status (activate/suspend/delete)
  async function changeStatus(userId, newStatus) {
    setError('');
    try {
      const res = await fetch(`/api/users/${userId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus }),
      });
      if (!res.ok) throw new Error('Failed');
      const updated = await res.json();
      setUsers(prev => prev.map(u => (u._id === updated._id || u.id === updated.id ? updated : u)));
      if (selectedUser && (selectedUser._id === userId || selectedUser.id === userId)) setSelectedUser(updated);
    } catch (err) {
      console.error(err);
      setError('Failed to change status');
    }
  }

  // Delete permanently
  async function deleteUser(userId) {
    if (!window.confirm('Permanently delete this user? This cannot be undone.')) return;
    setError('');
    try {
      const res = await fetch(`/api/users/${userId}`, { method: 'DELETE' });
      if (!res.ok) throw new Error('Failed to delete');
      setUsers(prev => prev.filter(u => (u._id || u.id) !== userId));
      closeModal();
    } catch (err) {
      console.error(err);
      setError('Failed to delete user');
    }
  }

  return (
    <div className="page-content">
      <style>{styles}</style>
      <div className="page-header">
        <div>
          <h2 className="page-title">User Management</h2>
          <div style={{ color: '#6b7280', fontSize: 13 }}>Search, filter and manage user accounts.</div>
        </div>

        <div className="controls">
          <input
            className="input"
            placeholder="Search by name or email"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
          <select className="select" value={statusFilter} onChange={e => setStatusFilter(e.target.value)}>
            <option value="All">All status</option>
            <option value="active">Active</option>
            <option value="deactivated">Deactivated</option>
            <option value="deleted">Deleted</option>
          </select>
        </div>
      </div>

      <div style={{ marginBottom: 12 }} className="tabs">
        {['All', 'Jobseekers', 'Employers', 'Admins'].map(t => (
          <button
            key={t}
            className={`tab ${roleTab === t ? 'active' : ''}`}
            onClick={() => setRoleTab(t)}
          >
            {t}
          </button>
        ))}
      </div>

      {error && <div style={{ color: 'red', marginBottom: 8 }}>{error}</div>}

      {loading ? (
        <div>Loading users…</div>
      ) : (
        <div className="card">
          <table className="table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Email</th>
              <th>Role</th>
              <th>Status</th>
              <th>Joined</th>
            </tr>
          </thead>
          <tbody>
            {filteredUsers.length === 0 ? (
              <tr>
                <td colSpan={5} style={{ padding: 20 }}>
                  No users found.
                </td>
              </tr>
            ) : (
              filteredUsers.map(u => (
                <tr key={u._id || u.id} className="row" onClick={() => openModal(u)}>
                  <td>
                    <div style={{ fontWeight: 600 }}>{u.fullName || '—'}</div>
                    <div style={{ fontSize: 12, color: '#6b7280' }}>{u.phone || ''}</div>
                  </td>
                  <td>{u.email || '—'}</td>
                  <td style={{ textTransform: 'capitalize' }}>{u.role || '—'}</td>
                  <td>
                    <span className={`badge ${((u.status || 'active') === 'active') ? 'active' : ((u.status || '') === 'deactivated') ? 'deactivated' : 'deleted'}`}>
                      {(u.status || 'active').toUpperCase()}
                    </span>
                  </td>
                  <td>{new Date(u.createdAt || u.created || Date.now()).toLocaleDateString()}</td>
                </tr>
              ))
            )}
          </tbody>
          </table>
        </div>
      )}

      {modalOpen && selectedUser && (
        <div className="modal-backdrop" onClick={closeModal}>
          <div className="modal" onClick={e => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <h3 style={{ margin: 0 }}>User Details</h3>
              <div style={{ fontSize: 13, color: '#6b7280' }}>{selectedUser.email}</div>
            </div>

            <div style={{ marginTop: 12 }}>
              <div className="form-row">
                <input
                  value={selectedUser.fullName || ''}
                  onChange={e => setSelectedUser(prev => ({ ...prev, fullName: e.target.value }))}
                />
                <input
                  value={selectedUser.email || ''}
                  onChange={e => setSelectedUser(prev => ({ ...prev, email: e.target.value }))}
                />
              </div>

              <div className="form-row">
                <select
                  value={selectedUser.role || ''}
                  onChange={e => setSelectedUser(prev => ({ ...prev, role: e.target.value }))}
                >
                  <option value="jobseeker">Jobseeker</option>
                  <option value="employer">Employer</option>
                  <option value="admin">Admin</option>
                </select>
                <input
                  placeholder="New password (support only)"
                  type="password"
                  value={selectedUser.newPassword || ''}
                  onChange={e => setSelectedUser(prev => ({ ...prev, newPassword: e.target.value }))}
                />
              </div>

              <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end', marginTop: 12 }}>
                <button className="btn" onClick={closeModal} disabled={saving}>
                  Close
                </button>
                <button
                  className="btn btn-primary"
                  onClick={() => saveUserEdits()}
                  disabled={saving}
                >
                  {saving ? 'Saving…' : 'Save changes'}
                </button>
              </div>

              <hr style={{ margin: '16px 0' }} />

              <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end' }}>
                {((selectedUser.status || 'active') !== 'active') && (
                  <button className="btn btn-primary" onClick={() => changeStatus(selectedUser._id || selectedUser.id, 'active')}>
                    Activate
                  </button>
                )}
                {((selectedUser.status || 'active') === 'active') && (
                  <button className="btn" onClick={() => changeStatus(selectedUser._id || selectedUser.id, 'deactivated')}>
                    Suspend
                  </button>
                )}
                <button className="btn btn-danger" onClick={() => deleteUser(selectedUser._id || selectedUser.id)}>
                  Delete
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
