import React, { useEffect, useState } from 'react';
import { useAuth } from '../../contexts/AuthContext';

export default function EmployerDashboard() {
  const { profile, token } = useAuth();

  const [stats, setStats] = useState({
    activeJobs: [],
    totalApplicants: 0,
    ongoingInterviews: [],
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    let cancelled = false;
    async function loadStats() {
      setLoading(true);
      setError(null);
      try {
        const base = process.env.REACT_APP_API_URL || '';

        // derive employer id from profile (support different shapes)
        const employerId = profile && (profile.userId || profile.id || profile._id || profile.employerId || profile.companyId);

        // Fetch jobs created by this employer
        let jobs = [];
        try {
          const jobsRes = await fetch(`${base}/api/jobs?createdBy=${encodeURIComponent(employerId || '')}`);
          if (jobsRes.ok) {
            const jobsData = await jobsRes.json();
            // jobs endpoint returns array
            jobs = Array.isArray(jobsData) ? jobsData : (jobsData && Array.isArray(jobsData.jobs) ? jobsData.jobs : []);
          }
        } catch (e) {
          console.warn('Failed to fetch employer jobs', e);
        }

        // Fetch applications for this employer
        let applications = [];
        try {
          const headers = { 'Content-Type': 'application/json' };
          if (token) headers.Authorization = `Bearer ${token}`;
          const appsRes = await fetch(`${base}/api/applications/employer/${encodeURIComponent(employerId || '')}`, { headers });
          if (appsRes.ok) {
            const appsData = await appsRes.json();
            applications = Array.isArray(appsData.applications) ? appsData.applications : (Array.isArray(appsData) ? appsData : []);
          }
        } catch (e) {
          console.warn('Failed to fetch employer applications', e);
        }

        // derive ongoing interviews by checking application status values
        const ongoing = (applications || []).filter(a => {
          const s = (a.status || '').toString().toLowerCase();
          if (!s) return false;
          return s.includes('interview') || s.includes('shortlist') || s.includes('scheduled') || s.includes('on hold') || s.includes('phone');
        });

        // normalize active jobs: include contactName and postedDate
        const activeJobs = (jobs || []).filter(j => String((j.status || 'Active')).toLowerCase() !== 'closed').map(j => ({
          ...j,
          contactName: j.contactName || profile?.companyName || '',
          postedDate: j.postedAt || j.postedDate || j.createdAt || null,
        }));

        if (!cancelled) setStats({ activeJobs, totalApplicants: (applications || []).length, ongoingInterviews: ongoing });
      } catch (err) {
        console.error('Failed to fetch dashboard stats:', err);
        if (!cancelled) setError(err.message || 'Failed to load stats');
      } finally {
        if (!cancelled) setLoading(false);
      }
    }
    loadStats();
    return () => { cancelled = true; };
  }, [token, profile]);

  const container = {
    padding: '32px',
    fontFamily: 'Segoe UI, sans-serif',
    backgroundColor: '#f4f6f8',
    minHeight: '100vh',
    display: 'flex',
    flexDirection: 'column',
    gap: '24px',
  };

  const heading = {
    fontSize: '28px',
    fontWeight: '600',
    color: '#333',
  };

  const subheading = {
    fontSize: '16px',
    color: '#555',
  };

  const grid = {
    display: 'grid',
    gridTemplateColumns: 'repeat(3, 1fr)',
    gap: '24px',
  };

  const squareCard = {
    backgroundColor: '#fff',
    borderRadius: '10px',
    padding: '24px',
    boxShadow: '0 2px 6px rgba(0,0,0,0.05)',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'center',
    minHeight: '200px',
  };

  const sectionTitle = {
    fontSize: '18px',
    fontWeight: '600',
    marginBottom: '12px',
    color: '#222',
  };

  const boldText = {
    fontSize: '24px',
    fontWeight: '700',
    color: '#333',
  };

  const pendingSection = {
    backgroundColor: '#fff',
    borderRadius: '10px',
    padding: '24px',
    boxShadow: '0 2px 6px rgba(0,0,0,0.05)',
  };

  const pendingList = {
    display: 'flex',
    flexDirection: 'column',
    gap: '16px',
  };

  const pendingItem = {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    backgroundColor: '#fff',
    padding: '16px',
    borderRadius: '8px',
    boxShadow: '0 1px 4px rgba(0,0,0,0.05)',
  };

  const leftInfo = {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
  };

  const circle = {
    width: '12px',
    height: '12px',
    borderRadius: '50%',
    backgroundColor: '#f97316',
  };

  const nameRole = {
    display: 'flex',
    flexDirection: 'column',
  };

  const lightText = {
    color: '#666',
    fontSize: '14px',
  };

  const status = {
    fontSize: '14px',
    color: '#444',
  };

  const viewLink = {
    color: '#0078d4',
    fontSize: '14px',
    textDecoration: 'none',
    fontWeight: '500',
  };

  return (
    <div style={container}>
      <div>
        <h1 style={heading}>Employer Dashboard</h1>
        <p style={subheading}>
          Welcome{profile?.companyName ? `, ${profile.companyName}` : ''} — manage your jobs and candidates here.
        </p>
      </div>

      <div style={grid}>
        <div style={squareCard}>
          <p style={sectionTitle}>Active Job Posts</p>
          {stats.activeJobs.length > 0 ? (
            <ul>
              {stats.activeJobs.map((job, i) => (
                <li key={i} style={lightText}>{job.title}</li>
              ))}
            </ul>
          ) : (
            <p style={lightText}>No active jobs yet.</p>
          )}
        </div>
        <div style={squareCard}>
          <p style={sectionTitle}>Total Applicants</p>
          <p style={boldText}>{stats.totalApplicants}</p>
        </div>
        <div style={squareCard}>
          <p style={sectionTitle}>Ongoing Interviews</p>
          <p style={boldText}>{stats.ongoingInterviews.length}</p>
        </div>
      </div>

      <div style={pendingSection}>
        <p style={sectionTitle}>Pending Approvals</p>
        <div style={pendingList}>
          {loading && <div style={{ padding: 12 }}>Loading…</div>}
          {error && <div style={{ padding: 12, color: '#c0392b' }}>Error: {error}</div>}
          {!loading && !error && stats.activeJobs.slice(0, 3).map((job, i) => (
            <div key={i} style={pendingItem}>
              <div style={leftInfo}>
                <div style={circle}></div>
                <div style={nameRole}>
                  <span style={boldText}>{job.contactName || 'Jane Smith'}</span>
                  <span style={lightText}>{job.title}</span>
                </div>
              </div>
              <span style={lightText}>{job.postedDate ? new Date(job.postedDate).toLocaleDateString() : '—'}</span>
              <span style={status}>{job.status || 'In Review'}</span>
              <button type="button" style={viewLink} onClick={() => { /* TODO: navigate to job details */ }}>{'View Details'}</button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
