import React, { useEffect, useState } from 'react';
import './admin.css';
import './JobApproval.css';
import { useAuth } from '../../contexts/AuthContext';

export default function JobApprovals() {
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchJobs();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const { token } = useAuth();

  const fetchJobs = () => {
    setLoading(true);
    fetch('/api/jobs')
      .then(res => {
        if (!res.ok) return res.json().then(err => { throw err; });
        return res.json();
      })
      .then(data => {
        // backend may return array or { jobs: [] }
        const arr = Array.isArray(data) ? data : (data.jobs || []);
        setJobs(arr);
        setLoading(false);
      })
      .catch(err => {
        console.error('Failed to fetch jobs:', err);
        setJobs([]);
        setLoading(false);
      });
  };

  const handleView = (job) => {
    const id = job._id || job.id;
    if (!id) return;
    // open job in a new tab (frontend route may vary)
    window.open(`/job/${id}`, '_blank');
  };

  const handleRefresh = () => fetchJobs();

  const handleDelete = async (job) => {
    const id = job._id || job.id;
    if (!id) return;
    const ok = window.confirm('Delete this job? This action cannot be undone.');
    if (!ok) return;
    if (!token) {
      alert('You must be signed in to delete jobs.');
      return;
    }
    try {
      const res = await fetch(`/api/jobs/${id}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        throw new Error(body && body.error ? body.error : 'delete failed');
      }
      // optimistic update
      setJobs(prev => prev.filter(j => String(j._id || j.id) !== String(id)));
    } catch (e) {
      console.error('Failed to delete job', e);
      alert('Failed to delete job: ' + (e.message || 'unknown error'));
    }
  };

  return (
    <div className="page-content">
      <div className="page-header">
        <h1 className="page-title">Job Listings</h1>
        <div className="muted">{loading ? 'Loading…' : `${jobs.length} jobs`}</div>
      </div>

      {loading ? (
        <div className="muted">Loading jobs…</div>
      ) : jobs.length === 0 ? (
        <div className="card empty">No jobs found.</div>
      ) : (
        <div className="card">
          <table className="job-table">
            <thead>
              <tr>
                <th>Title</th>
                <th>Company</th>
                <th>Location</th>
                <th>Type</th>
                  <th>Posted</th>
                  <th style={{ width: 220 }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {jobs.map((job, i) => (
                <tr key={job._id || job.id || i} className="job-row">
                  <td>{job.title || job.jobTitle || '—'}</td>
                  <td>{job.companyName || job.company || (job.employer && job.employer.companyName) || '—'}</td>
                  <td>{job.location || job.city || '—'}</td>
                  <td>{job.jobType || job.type || '—'}</td>
                  <td>{new Date(job.createdAt || job.created || Date.now()).toLocaleDateString()}</td>
                    <td>
                      <div className="job-actions">
                        <button type="button" className="btn btn-secondary" onClick={() => handleView(job)}>View</button>
                        <button type="button" className="btn" onClick={() => handleRefresh()}>Refresh</button>
                        <button type="button" className="btn btn-danger" onClick={() => handleDelete(job)}>Delete</button>
                      </div>
                    </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
