import React, { useEffect, useState, useRef } from 'react';
import './Messages.css';
import { useAuth } from '../../contexts/AuthContext';
import {
  getConversations,
  getMessages,
  sendMessage,
  startConversation,
  archiveConversation,
  deleteConversation,
} from '../../api/messages';
import { getOwnProfile } from '../../api/profile';
import { useLocation } from 'react-router-dom';

function initialsFromTitle(title) {
  if (!title) return 'U';
  const parts = title.split(/\s+/).filter(Boolean);
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[1][0]).toUpperCase();
}

export default function Messages() {
  const { profile, token } = useAuth();
  const userId = profile?.userId || profile?._id || null;
  const userType =
    profile?.userType ||
    profile?.type ||
    (profile?.company ? 'EmployersProfile' : 'Profile');

  const [convos, setConvos] = useState([]);
  const [selected, setSelected] = useState(null);
  const [messages, setMessages] = useState([]);
  const [otherName, setOtherName] = useState('');
  const [text, setText] = useState('');
  const [filter, setFilter] = useState('All');
  const [search, setSearch] = useState('');
  const threadRef = useRef(null);
  const location = useLocation();

  // Load conversations
  useEffect(() => {
    if (!userId) return;
    getConversations(userId, userType, filter === 'Archived')
      .then((d) => {
        const list = (d.conversations || []).map((c) => ({
          ...c,
          archived:
            Array.isArray(c.archivedBy) &&
            c.archivedBy.some((a) => String(a.userId) === String(userId)),
        }));
        setConvos(list);
      })
      .catch(() => {});
  }, [userId, userType, filter]);

  // Load messages when selecting a conversation
  useEffect(() => {
    if (!selected) return;
    getMessages(selected._id)
      .then((d) => setMessages(d.messages || []))
      .catch(() => {});
  }, [selected]);

  // Scroll to bottom on new messages
  useEffect(() => {
    if (threadRef.current)
      threadRef.current.scrollTop = threadRef.current.scrollHeight;
  }, [messages]);

  // Determine other participant's name
  useEffect(() => {
    if (!selected) {
      setOtherName('');
      return;
    }

    (async () => {
      try {
        if (selected.title) {
          setOtherName(selected.title);
          return;
        }

        const participants = Array.isArray(selected.participants)
          ? selected.participants
          : [];

        const myIds = new Set(
          [profile?._id, profile?.userId, profile?.id]
            .filter(Boolean)
            .map(String)
        );

        let other = participants.find(
          (p) => !myIds.has(String(p?.userId || p))
        );
        if (!other && participants.length > 0) other = participants[0];

        if (!other) {
          setOtherName('Conversation');
          return;
        }

        const display =
          other.company ||
          other.fullName ||
          `${other.firstName || ''} ${other.lastName || ''}`.trim() ||
          other.email ||
          'Conversation';
        setOtherName(display);
      } catch {
        setOtherName('Conversation');
      }
    })();
  }, [selected, profile]);

  // Handle sending messages
  const handleSend = async () => {
    if (!text || !selected || !userId) return;

    try {
      const toParticipant = selected.participants.find(
        (p) => String(p.userId || p) !== String(userId)
      );

      const toType =
        toParticipant?.userType ||
        (userType === 'EmployersProfile' ? 'Profile' : 'EmployersProfile');

      const res = await sendMessage({
        conversationId: selected._id,
        from: userId,
        fromType: userType,
        to: toParticipant?.userId || toParticipant,
        toType,
        body: text,
        title: selected?.title,
      });

      // Append new message to chat
      setMessages((prev) => [...prev, res.message]);
      setText('');

      // Update conversation list instantly
      setConvos((prev) => {
        const idx = prev.findIndex((c) => c._id === selected._id);
        const updatedConvo = {
          ...selected,
          lastMessage: text,
          updatedAt: new Date().toISOString(),
        };
        if (idx >= 0) {
          const copy = [...prev];
          copy.splice(idx, 1);
          return [updatedConvo, ...copy];
        }
        return [updatedConvo, ...prev];
      });
    } catch (e) {
      console.warn('Send failed', e);
    }
  };

  // Handle conversation start from navigation state
  useEffect(() => {
    const state = location?.state;
    if (!state || !userId) return;

    const target = state.toApplicantId || state.toUserId || state.toEmail;
    const title = state.toName || '';

    if (!target) return;

    const fromType = userType;
    const toType =
      state?.toUserType ||
      (fromType === 'EmployersProfile' ? 'Profile' : 'EmployersProfile');

    (async () => {
      try {
        const res = await startConversation(userId, target, title, fromType, toType);
        const conv = res.conversation || res.conversationCreated || res;
        const d = await getConversations(userId, userType, false);
        const list = (d.conversations || []).map((c) => ({
          ...c,
          archived:
            Array.isArray(c.archivedBy) &&
            c.archivedBy.some((a) => String(a.userId) === String(userId)),
        }));
        setConvos(list);
        setSelected(
          list.find((c) => c._id === conv._id) ||
            conv ||
            (list && list[0]) ||
            null
        );
      } catch (e) {
        console.warn('Could not start/select conversation', e);
      }
    })();
  }, [location.state, userId, userType]);

  const filteredConvos = convos.filter((c) => {
    if (!c) return false;
    if (filter === 'Archived') return !!c.archived;
    if (search.trim()) {
      const t = (c.title || '').toLowerCase();
      return t.includes(search.toLowerCase());
    }
    return true;
  });

  return (
    <div className="messages-root page-content" style={{ padding: 24 }}>
      <div className="messages-card">
        <aside className="messages-list">
          <div className="panel panel-left">
            <div className="panel-header">
              <div className="panel-title">Conversations</div>
            </div>
            <div className="panel-body">
              <div className="messages-search">
                <input
                  className="wc-search"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  placeholder="Search conversations"
                />
              </div>

              <div className="messages-filters">
                {['All', 'Archived'].map((f) => (
                  <button
                    key={f}
                    className={`filter-btn ${filter === f ? 'active' : ''}`}
                    onClick={() => setFilter(f)}
                  >
                    {f}
                  </button>
                ))}
              </div>

              <div className="messages-convos">
                {filteredConvos.map((c) => (
                  <div
                    key={c._id}
                    className={`messages-convo ${
                      selected && selected._id === c._id ? 'active' : ''
                    }`}
                    onClick={() => setSelected(c)}
                  >
                    <div className="convo-left">
                      <div className="avatar">
                        {initialsFromTitle(c.title)}
                      </div>
                    </div>
                    <div className="convo-body">
                      <div className="convo-title-row">
                        <div className="convo-title">
                          {c.title || 'Conversation'}
                        </div>
                        <div className="convo-time">
                          {c.updatedAt
                            ? new Date(c.updatedAt).toLocaleTimeString([], {
                                hour: '2-digit',
                                minute: '2-digit',
                              })
                            : ''}
                        </div>
                      </div>
                      <div className="convo-last">{c.lastMessage}</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </aside>

        <main className="messages-thread">
          <div className="panel panel-right">
            <div className="panel-header">
              <div className="panel-title">
                {selected
                  ? otherName || selected.title || 'Conversation'
                  : 'Active Chat Area'}
              </div>
            </div>
            <div className="panel-body panel-body-right">
              {!selected && (
                <div className="messages-empty">
                  Select a conversation or start a new one
                </div>
              )}
              {selected && (
                <>
                  <div className="thread-body" ref={threadRef}>
                    {messages.map((m) => (
                      <div
                        key={m._id}
                        className={`thread-msg ${
                          String(m.from) === String(userId) ? 'me' : 'them'
                        }`}
                      >
                        <div className="msg-body">{m.body}</div>
                        <div className="msg-meta">
                          {new Date(m.createdAt).toLocaleTimeString([], {
                            hour: '2-digit',
                            minute: '2-digit',
                          })}
                        </div>
                      </div>
                    ))}
                  </div>

                  <div className="thread-input">
                    <input
                      value={text}
                      onChange={(e) => setText(e.target.value)}
                      placeholder="Type a message"
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          handleSend();
                        }
                      }}
                    />
                    <button className="send-btn" onClick={handleSend}>
                      ➤
                    </button>
                  </div>
                </>
              )}
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}
